/* @lc app=leetcode id=3801 lang=kotlin */ class Solution { fun ub(a: IntArray, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun minMergeCost(lists: Array<IntArray>): Long = lists.size.let { n -> (1 shl n).let { F -> IntArray(F).also { ln -> (1 until F).forEach { m -> ln[m] = ln[m and (m - 1)] + lists[Integer.numberOfTrailingZeros(m)].size } }.let { ln -> LongArray(F).also { md -> (1 until F).forEach { m -> ((ln[m] + 1) / 2).let { kk -> md[m] = generateSequence(-1_000_000_000L to 1_000_000_000L) { (lo, hi) -> if (lo >= hi) null else Math.floorDiv(lo + hi, 2L).let { v -> if ((0 until n).filter { m shr it and 1 == 1 }.sumOf { ub(lists[it], v) } >= kk) lo to v else v + 1 to hi } }.last().first } } }.let { md -> LongArray(F) { Long.MAX_VALUE / 4 }.also { dp -> (0 until n).forEach { dp[1 shl it] = 0L } }.also { dp -> (1 until F).forEach { m -> if (m and (m - 1) != 0) generateSequence(m) { s -> if (s == 0) null else (s - 1) and m }.filter { it != 0 && it != m && (it and (m and -m)) != 0 }.forEach { sub -> (m xor sub).let { rest -> dp[m] = minOf(dp[m], dp[sub] + dp[rest] + ln[sub] + ln[rest] + Math.abs(md[sub] - md[rest])) } } } }.last() } } } } }